/* From Uiverse.io by ahmedyasserdev  - Tags: checkbox, hamburger, rotate, menu */
.__UIV_SCOPE__ .burger {
  display: inline-block;
  cursor: pointer;
  z-index: 1000;
}

.__UIV_SCOPE__ .burger span {
  display: block;
  width: 30px;
  height: 3px;
  background: #333;
  margin: 6px 0;
  transition: transform 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55),
    opacity 0.3s ease;
}

.__UIV_SCOPE__ #burger-checkbox {
  display: none;
}

.__UIV_SCOPE__ #burger-checkbox:checked + .burger span:nth-child(1) {
  transform: translateY(8px) rotate(45deg);
}

.__UIV_SCOPE__ #burger-checkbox:checked + .burger span:nth-child(2) {
  opacity: 0;
  transform: translateX(-20px);
}

.__UIV_SCOPE__ #burger-checkbox:checked + .burger span:nth-child(3) {
  transform: translateY(-8px) rotate(-45deg);
}
